-- 0213: the booking's calendar link in the confirmation email, and Apple Wallet (Release 22, item 2). SCHEMA_MARKER 0213.
-- docs/changes/2026-11-02-wallet-calendar.md.
--   1. bookings.calendar_token: a random link key for the booking's calendar file (/api/booking-ics/<token>: pickup and
--      return as two events with the address), so the link works from the email without signing in. It shows only the
--      car, the times and the place.
--   2. renter_booking_confirmed gets calendar_url ("Add pickup and return to my calendar"); the booking page already has
--      Add to calendar.
--   3. Apple Wallet needs no database change: the pass is built from the renter's own booking on the site
--      (/account/bookings/<number>/wallet) and shows only once the Pass Type ID certificate is set (the Worker's secrets).
set local check_function_bodies = off;

create function pg_temp.copy_grants(p_new regprocedure, p_old regprocedure) returns void
language plpgsql as $$
declare g text;
begin
  execute format('revoke all on function %s from public, anon, authenticated', p_new);
  foreach g in array array['anon', 'authenticated', 'service_role'] loop
    if has_function_privilege(g, p_old, 'execute') then execute format('grant execute on function %s to %I', p_new, g); end if;
  end loop;
end $$;

alter table bookings add column if not exists calendar_token uuid not null default gen_random_uuid();
create unique index if not exists bookings_calendar_token_key on bookings (calendar_token);
comment on column bookings.calendar_token is 'The key of the booking''s calendar link (0213): /api/booking-ics/<token>, from the confirmation email. Only the car, times and place.';

-- the calendar file's facts: only while the booking is confirmed or on rent
create or replace function public.server_booking_calendar(p_token uuid) returns jsonb
language sql stable security definer set search_path = public, app as $$
  select jsonb_build_object('number', b.booking_number, 'car', app.vehicle_name(b.vehicle_id), 'pickup_at', b.pickup_at, 'return_at', b.return_at,
           'pickup_place', coalesce(nullif(b.pickup_place, ''), (select coalesce(nullif(s.street_address, ''), s.city, 'CarmaCars') from site_settings s limit 1)),
           'return_place', nullif(b.return_place, ''))
    from bookings b where b.calendar_token = p_token and b.status in ('confirmed', 'on_rent')
$$;
revoke all on function public.server_booking_calendar(uuid) from public, anon, authenticated;
grant execute on function public.server_booking_calendar(uuid) to service_role;

alter function app.notification_payload(text, app_events, jsonb) rename to ntf_payload_pre0213;
create function app.notification_payload(p_code text, p_event app_events, p_to jsonb) returns jsonb
language plpgsql stable security definer set search_path = public, app as $$
declare x jsonb := app.ntf_payload_pre0213(p_code, p_event, p_to);
begin
  if p_code = 'renter_booking_confirmed' then
    x := coalesce(x, '{}'::jsonb) || jsonb_build_object('calendar_url', coalesce((select rtrim((app.settings()).notify_base_url, '/') || '/api/booking-ics/' || b.calendar_token
                   from bookings b where b.id = coalesce((p_event.payload ->> 'booking_id')::uuid, case when p_event.entity = 'booking' then p_event.entity_id end)), ''));
  end if;
  return x;
end $$;
select pg_temp.copy_grants('app.notification_payload(text, app_events, jsonb)'::regprocedure, 'app.ntf_payload_pre0213(text, app_events, jsonb)'::regprocedure);
revoke all on function app.ntf_payload_pre0213(text, app_events, jsonb) from public, anon, authenticated;
grant execute on function app.ntf_payload_pre0213(text, app_events, jsonb) to service_role;

